// Join PG rows and Shopify orders on order_id, classify each.
const pgRows = $('Read Recent Rows (Postgres)').all().map(i => i.json);
const shRows = $('Read Recent Orders (Shopify)').all().map(i => i.json);
const pg = new Map(pgRows.map(r => [String(r.order_id), r]));
const sh = new Map(shRows.map(r => [String(r.id), { total: Number(r.total_price||0), financial_status: r.financial_status }]));
const ids = new Set([...pg.keys(), ...sh.keys()]);
const out = [];
for (const id of ids) {
  const p = pg.get(id), s = sh.get(id);
  let drift = 'ok';
  if (p && !s) drift = 'missing_in_shopify';
  else if (!p && s) drift = 'missing_in_postgres';
  else if (Math.abs(Number(p.total) - s.total) > 0.001) drift = 'total_mismatch';
  else if (p.financial_status !== s.financial_status) drift = 'status_mismatch';
  out.push({ json: { order_id: id, drift, pg_total: p ? p.total : null, sh_total: s ? s.total : null, pg_status: p ? p.financial_status : null, sh_status: s ? s.financial_status : null } });
}
return out;

